"""Blender clip export (JSON, nd_io.export) -> src/Client/AuthoredClips.luau.
Usage: python3 clips_to_luau.py out.luau clips_a.json [clips_b.json ...]"""
import json, sys

def fmt(v):
    s = ("%.4f" % v).rstrip("0").rstrip(".")
    return "0" if s in ("-0", "") else s

HEADER = ["-- GENERATED by tools/blender/clips_to_luau.py from the Blender pipeline",
          "-- (tools/blender, Documents/NinjaDuelBlender). Do not edit by hand:",
          "-- re-author in Blender and re-export. Rows: Root = x,y,z,qx,qy,qz,qw;",
          "-- other joints = qx,qy,qz,qw; Roblox axes (Motor6D.Transform)."]
CHUNK = 180000  # characters per module


# ------------------------------------------------------------ film pass
# (User 28/10: "travaille-les pas comme des poses image par image, mais comme
# des mouvements fluides, comme un film".) Measured on the exports: 81 strikes
# froze dead for 4-10 frames right after the blow (pose -> snap -> freeze ->
# recover: stop-motion), and the backpedals' guards stepped 11 degrees in one
# frame where the mirrored half began. Two passes, applied to every export:
#   moving_holds: a hold after a fast move keeps moving - each joint carries on
#     a little in the direction it was going, then settles back onto the
#     authored pose by the end of the hold (overshoot and settle), so the
#     recovery starts exactly where it was keyed.
#   destep: in a looping clip, a joint that turns most of its cycle in one
#     frame spreads that turn over the frames around it.
import math


def _qmul(a, b):
    ax, ay, az, aw = a
    bx, by, bz, bw = b
    return [aw * bx + ax * bw + ay * bz - az * by, aw * by - ax * bz + ay * bw + az * bx,
            aw * bz + ax * by - ay * bx + az * bw, aw * bw - ax * bx - ay * by - az * bz]


def _qinv(a):
    return [-a[0], -a[1], -a[2], a[3]]


def _qnorm(a):
    n = math.sqrt(sum(v * v for v in a)) or 1.0
    return [v / n for v in a]


def _axis_angle(q):
    q = _qnorm(q)
    if q[3] < 0:
        q = [-v for v in q]
    w = max(-1.0, min(1.0, q[3]))
    ang = 2 * math.acos(w)
    s = math.sqrt(max(1e-12, 1 - w * w))
    return [q[0] / s, q[1] / s, q[2] / s], ang


def _rot(axis, ang):
    h = ang / 2
    s = math.sin(h)
    return [axis[0] * s, axis[1] * s, axis[2] * s, math.cos(h)]


def _quat_rows(joint, rows):
    return [r[3:7] if joint == "Root" else r[0:4] for r in rows]


def _set_quat(joint, row, q):
    q = _qnorm(q)
    return row[:3] + q if joint == "Root" else q


def _ang(a, b):
    d = min(1.0, abs(sum(x * y for x, y in zip(a, b))))
    return math.degrees(2 * math.acos(d))


HOLD = {"quiet": .07, "fast": .4, "min": 3, "gain": 1.6, "cap": 10.0}


def moving_holds(c):
    n = c["frames"]
    if c.get("loop") or n < 8:
        return 0
    js = {j: _quat_rows(j, r) for j, r in c["joints"].items()}
    tot = [sum(_ang(q[i], q[i + 1]) for q in js.values()) for i in range(n - 1)]
    peak = max(tot) or 1.0
    holds, i = [], 0
    while i < n - 1:
        if tot[i] < HOLD["quiet"] * peak:
            j = i
            while j < n - 1 and tot[j] < HOLD["quiet"] * peak:
                j += 1
            if j - i >= HOLD["min"] and i > 0 and max(tot[max(0, i - 2):i]) > HOLD["fast"] * peak and j < n - 1:
                holds.append((i, j - i))
            i = j
        else:
            i += 1
    for start, length in holds:
        for joint, rows in c["joints"].items():
            q = js[joint]
            axis, step = _axis_angle(_qmul(q[start], _qinv(q[start - 1])))
            if step < math.radians(.5):
                continue
            amp = min(math.radians(HOLD["cap"]), step * HOLD["gain"])
            # frames start .. start+length: rise, then settle back on the key
            for k in range(length + 1):
                f = start + k
                if f >= n:
                    break
                off = amp * math.sin(math.pi * (k + 1) / (length + 2))
                rows[f] = _set_quat(joint, rows[f], _qmul(_rot(axis, off), q[f]))
    return len(holds)


def destep(c):
    n = c["frames"]
    if not c.get("loop") or n < 12:
        return 0
    m = n - 1  # the last frame repeats the first: a cycle of m frames
    fixed = 0
    for joint, rows in c["joints"].items():
        for _ in range(4):
            q = _quat_rows(joint, rows)
            sp = [_ang(q[i], q[(i + 1) % m]) for i in range(m)]
            total = sum(sp)
            if total < 6:
                break
            i = max(range(m), key=lambda k: sp[k])
            if not (sp[i] > 5 and sp[i] > .3 * total):
                break
            # spread the turn i -> i+1 over 4 frames each side (smoothstep)
            a, b = q[i], q[(i + 1) % m]
            axis, ang = _axis_angle(_qmul(b, _qinv(a)))
            new = {}
            for k in range(-4, 5):
                f = (i + k) % m
                t = (k + 4.5) / 9.0
                u = t * t * (3 - 2 * t)
                base = a if k <= 0 else b
                drift = _qmul(q[f], _qinv(base))
                new[f] = _qmul(drift, _qmul(_rot(axis, ang * u), a))
            for f, v in new.items():
                rows[f] = _set_quat(joint, rows[f], v)
            rows[m] = _set_quat(joint, rows[m], _quat_rows(joint, [rows[0]])[0])
            fixed += 1
    return fixed


def clip_lines(name, c):
    markers = ",".join("%s=%s" % (k, fmt(v)) for k, v in sorted(c["markers"].items()))
    meta = ",".join("%s=%s" % (k, fmt(v)) for k, v in sorted(c.get("meta", {}).items()) if isinstance(v, (int, float)))
    lines = ['\t["%s"]={fps=%d,frames=%d,length=%s,loop=%s,markers={%s},meta={%s},joints={' % (
        name, c["fps"], c["frames"], fmt(c["length"]), "true" if c["loop"] else "false", markers, meta)]
    for joint, rows in c["joints"].items():
        lines.append("\t\t%s={%s}," % (joint, ",".join(fmt(v) for row in rows for v in row)))
    lines.append("\t}},")
    return lines


def main(out, inputs):
    """out: path of AuthoredClips.luau; the data goes to AuthoredClips1..N
    next to it (each under CHUNK characters) and AuthoredClips merges them."""
    import os
    clips = {}
    for p in inputs:
        clips.update(json.load(open(p)))
    held = stepped = 0
    for c in (clips.values() if not os.environ.get('ND_NO_FILM') else []):
        held += moving_holds(c)
        stepped += destep(c)
    print("film pass:", held, "dead holds made moving,", stepped, "stepped loop joints eased")
    folder, base = os.path.dirname(out), os.path.basename(out)[:-5]
    for f in os.listdir(folder):
        if f.startswith(base) and f[len(base):-5].isdigit() and f.endswith(".luau"):
            os.remove(os.path.join(folder, f))
    chunks, cur, size = [], [], 0
    for name in sorted(clips):
        lines = clip_lines(name, clips[name])
        n = sum(len(l) + 1 for l in lines)
        if cur and size + n > CHUNK:
            chunks.append(cur)
            cur, size = [], 0
        cur.extend(lines)
        size += n
    if cur:
        chunks.append(cur)
    for i, body in enumerate(chunks, 1):
        open(os.path.join(folder, "%s%d.luau" % (base, i)), "w").write("\n".join(HEADER + ["return {"] + body + ["}"]) + "\n")
    agg = HEADER[:1] + ["-- The clips are split over %s1..%d (module size); merged here." % (base, len(chunks)), "local all={}"]
    for i in range(1, len(chunks) + 1):
        agg.append("for name,clip in require(script.Parent.%s%d) do all[name]=clip end" % (base, i))
    agg.append("return all")
    open(out, "w").write("\n".join(agg) + "\n")
    print(out, len(clips), "clips in", len(chunks), "modules")


if __name__ == "__main__":
    main(sys.argv[1], sys.argv[2:])
